function Field({ label, children, wide = false, hint }: { label: string; children: ReactNode; wide?: boolean; hint?: string }) { return <label className={`field ${wide ? 'field-wide' : ''}`}><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }

function ClerkCacheClearer() {
  const { addListener } = useClerk();
  const qc = useQueryClient();
  useEffect(() => {
    let previous: string | null | undefined;
    return addListener(({ user }) => { const next = user?.id ?? null; if (previous !== undefined && previous !== next) qc.clear(); previous = next; });
  }, [addListener, qc]);
  return null;
}
function ClerkProfileSync() {
  const { user, isLoaded } = useUser();
  const sync = useSyncCurrentUser();
  const qc = useQueryClient();
  useEffect(() => {
    if (isLoaded && user && !sync.isPending) {
      sync.mutate({ data: { name: user.fullName || user.firstName || user.primaryEmailAddress?.emailAddress || 'Operador', email: user.primaryEmailAddress?.emailAddress || '' } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getGetCurrentUserQueryKey() }) });
    }
  // Deliberately sync once when Clerk resolves the signed-in identity.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isLoaded, user?.id]);
  return null;
}
