    <aside className={`sidebar ${mobileOpen ? 'sidebar-open' : ''}`}><div className="side-head"><Link href="/dashboard"><Brand light/></Link><button className="icon-button mobile-close" aria-label="Fechar menu" onClick={() => setMobileOpen(false)}><X size={18}/></button></div><div className="side-label">ESPAÇO DE TRABALHO</div><nav className="side-nav">{navItems.map(({ href, label, icon: Icon }) => <Link key={href} href={href} className={`side-link ${location.startsWith(href) ? 'side-link-active' : ''}`} onClick={() => setMobileOpen(false)}><Icon size={18}/><span>{label}</span>{href === '/clients' && <span className="nav-indicator"/>}</Link>)}</nav><div className="side-bottom"><div className="workspace-badge"><div className="workspace-icon"><BriefcaseBusiness size={16}/></div><div><b>Minha carteira</b><span>Módulo financeiro 01</span></div><ChevronDown size={14}/></div><div className="user-chip"><div className="user-initial">{(currentUser?.name || 'O').slice(0,1).toUpperCase()}</div><div className="user-data"><b>{isLoading ? 'Carregando…' : currentUser?.name || 'Operador'}</b><span>{currentUser?.role === 'ADMIN' ? 'Administrador' : currentUser?.role === 'COBRADOR' ? 'Cobrador' : 'Conta Carteras'}</span></div><button className="icon-button logout-icon" aria-label="Encerrar sessão" title="Encerrar sessão" onClick={() => signOut({ redirectUrl: basePath || '/' })}><LogOut size={16}/></button></div></div></aside>
